/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `media_tag` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(32) NOT NULL COMMENT '标签名（去首尾空格后 1-32 字符，全局唯一）',
  `parent_id` bigint DEFAULT NULL COMMENT '父标签 id，关联 media_tag.id；NULL = 顶层标签',
  `color` varchar(16) DEFAULT NULL COMMENT '标签颜色（可空；建议 #RRGGBB）',
  `use_count` int NOT NULL DEFAULT '0' COMMENT '引用次数（media_video_tag 中 tag_id 相同的行数，写入时重算）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tag_name` (`name`),
  KEY `idx_tag_use_count` (`use_count`),
  KEY `idx_tag_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=133 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='媒体-标签字典';
